s=open(src,encoding='utf-8').read()
m=re.search(r'const DEFAULT_PACKS = (\[[\s\S]*?\n\]);',s); packs=json.loads(m.group(1))
n=0
for p in packs:
    for l in p['lessons']:
        k=(p['id'],l['no'])
        if k in NB and "class='nyushi'" not in l['html']:
            l['html']+=rubify("<div class='nyushi'><span class='bx-tag'>入試ではこう出る</span>"+NB[k]+"</div>"); n+=1
    if p['id'] in RJ and not p.get('ronjutsu'): p['ronjutsu']=RJ[p['id']]; n+=1
    if p['id']=='theme_kahei' and not p.get('cloze'):
        ans=[];
        for c in CL: ans+=re.findall(r'\[\[([^\]]+)\]\]',c['text'])
        pl=''.join(re.sub(r'\[\[[^\]]+\]\]','□',c['text']) for c in CL)
        print('kahei cloze',len(ans),'leak',[a for a in set(ans) if a in pl],'ov',[(a,b) for a in set(ans) for b in set(ans) if a!=b and a in b])
        p['cloze']=CL; n+=1
print('added',n)
s=s[:m.start(1)]+json.dumps(packs,ensure_ascii=False,indent=1)+s[m.end(1):]
open(out,'w',encoding='utf-8').write(s)
